"""Public schemas for the independent, single-profile RViz2/Nav2 plugin."""
ROBOT = {"robot_id": {"type": "string", "description": "Optional assertion: must match the configured robot; never switches profiles."}}
PATH = {"type": "string", "description": "Absolute path on the ROS host."}
POSE = {name: {"type": "number"} for name in ("x_m", "y_m", "yaw_rad")}
GOAL = {"goal_id": {"type": "string", "description": "ID returned by rviz2_set_goal for the current map, profile and verified initial pose."}}
TOOLS = [
    ("rviz2_configure_robot", "nav_configure_robot",
     "Configure one robot before loading RViz assets. Supply exactly profile_name=rv1 (baseline), profile_name=rv1_max_speed (2.5 m/s opt-in; Isaac must be prepared with the same limit), OR a complete profile object from the skill. The ros2 backend requires external TF/odom and never contacts Isaac. Changing profile requires rviz2_navigation_stop first; no simultaneous multi-robot support.",
     {"profile_name": {"type": "string", "enum": ["rv1", "rv1_max_speed"]}, "profile": {"type": "object", "description": "Validated robot_id, frames, topics, use_sim_time, params_file, localization_mode, control_backend; optional footprint, padding, limits and allow_lateral. Read skill for exact fields."}}, []),
    ("rviz2_open", "nav_open_rviz", "Open managed RViz2 on an existing X display using the configured map frame and topics. Requires a robot profile. Does not start Isaac or navigation.",
     {**ROBOT, "display_number": {"type": "integer", "minimum": 0, "maximum": 99, "description": "Existing X display; omit to use deployment display_number"}}, []),
    ("rviz2_close", "nav_close_rviz", "Close only the owned RViz2 window. Does not stop Nav2 or cancel a goal; use rviz2_cancel_navigation for motion and rviz2_navigation_stop for the full stack.", ROBOT, []),
    ("rviz2_load_map", "nav_map_load", "Load a ROS map YAML and its image into the managed map server and configured map topic. Cancels navigation and invalidates previous goals/initial pose. Does not convert USD.", {**ROBOT, "map_yaml_path": PATH}, ["map_yaml_path"]),
    ("rviz2_load_robot", "nav_model_load", "Load a robot URDF into robot_state_publisher on configured description/joint topics. Root link must match the profile base frame. Does not spawn or control a simulator robot.", {**ROBOT, "urdf_path": PATH}, ["urdf_path"]),
    ("rviz2_navigation_start", "nav_start", "Start managed Nav2 nodes with the configured robot's Nav2 parameters, footprint, frames and topics. Requires map and model loaded. Poll navigation status until ready. Does not generate a goal or arm robot motion.", {**ROBOT, "params_file": {**PATH, "description": "Optional consistency assertion; must equal the configured profile params_file. To change parameters stop and configure a new profile."}}, []),
    ("rviz2_navigation_status", "nav_status", "Read robot/profile, map, model, measured TF/odometry freshness, relay state, processes, goals, path and Nav2 action status. Does not start a worker. accepted/pending is not navigation success.", ROBOT, []),
    ("rviz2_set_initial_pose", "nav_set_initial_pose", "Verify an initial map-frame XY/yaw against the robot's existing fresh TF. Does not teleport a robot or publish an AMCL initialpose. A localization provider must already supply map->odom->base; simulation-truth is explicitly labeled.", {**ROBOT, **POSE}, list(POSE)),
    ("rviz2_set_goal", "nav_set_goal", "Validate a finite map-frame XY/yaw target against map bounds and the configured robot footprint. Returns goal_id. Agent chooses a destination; Nav2 performs all path planning and motion control.", {**ROBOT, **POSE}, list(POSE)),
    ("rviz2_plan_path", "nav_plan", "Ask Nav2 ComputePathToPose to plan to the recorded goal using the configured planner and full footprint. Does not publish drive commands. Requires verified initial pose and ready navigation.", {**ROBOT, **GOAL}, ["goal_id"]),
    ("rviz2_navigate", "nav_navigate", "Submit the recorded goal to Nav2 NavigateToPose after fresh TF/odom and readiness checks. Only Nav2 velocities reach the configured cmd_vel through a bounded watchdog relay. Poll status to verify SUCCEEDED and measured rest; no agent waypoint or velocity commands.", {**ROBOT, **GOAL}, ["goal_id"]),
    ("rviz2_cancel_navigation", "nav_cancel", "Disarm the velocity relay, publish zero, and cancel owned Nav2 goals. For isaac_rv1 additionally disarm its simulator subscriber. Poll status until the action is terminal and measured motion has stopped.", ROBOT, []),
    ("rviz2_navigation_stop", "nav_stop", "Cancel navigation, disarm and stop all owned Nav2, map-server, robot-state-publisher and RViz children. Keeps the bridge/profile available and does not close Isaac. Verify owned_processes_remaining=0.", ROBOT, []),
]
